// ];

interface NavbarProps {
  sidebarWidth?: number;
  navItems?: NavItem[];
  title?: string;
}

const Navbar: React.FC<NavbarProps> = ({ sidebarWidth = 280}) => {
  return (
    <header
      style={{
        position: 'fixed',
        top: 0,
        left: sidebarWidth,
        right: 0,
        height: 64,
        background: '#ffffff',
        borderBottom: '1px solid #E1E4EA',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '0 16px',
        boxSizing: 'border-box',
        zIndex: 99,
        transition: 'left 0.25s ease',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        {/* <span style={{ fontSize: 16, fontWeight: 700, color: '#0f172a' }}>{title}</span> */}
        <nav style={{ display: 'flex', gap: 8, marginLeft: 12 }}>

            {/* <NavLink
              key={item.id}
              to={item.path}
              style={({ isActive }) => ({
                textDecoration: 'none',
                color: isActive ? '#0b69ff' : '#475569',
                padding: '6px 10px',
                borderRadius: 6,
                fontWeight: isActive ? 600 : 400,
              })}
            >
              {item.label}
            </NavLink> */}

        </nav>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <div
          style={{
            width: 36,
            height: 36,
            borderRadius: '50%',
            background: '#E1E4EA',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontWeight: 600,
          }}
        >
          U
        </div>
      </div>
    </header>
  );
};

export default Navbar;
